{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In pigs, IV [11C](R)-16 entered the brain with a peak SUV of ~2.5 g/mL, demonstrating direct BBB passage after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In rats, [11C]4 entered the brain rapidly after IV injection, reaching ~1.2 SUV at 3–5 min, indicating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In rats, [11C]6 showed low whole-brain uptake (0.189 %ID/g at 5 min), indicating poor CNS access for that analog.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple direct in-vivo records across pigs, rats, mice, and monkeys show BBB penetration and brain uptake for close analogs, outweighing the limited negative analog signals; therefore predict pass for meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental record for the query molecule; evidence is transferred from analogs with moderate Morgan similarity.",
    "Negative analog signals, including low whole-brain uptake and an efflux-substrate profile, introduce uncertainty about uniform transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

